import { WeathercloudClient } from "../../src/Client";
import { mockServerPool } from "../mock-server/MockServerPool";

describe("ForecastClient", () => {
    test("getDaily", async () => {
        const server = mockServerPool.createServer();
        const client = new WeathercloudClient({ maxRetries: 0, requestedWith: "test", environment: server.baseUrl });

        const rawResponseBody = {
            info: { source: "WMO", web: "https://worldweather.wmo.int", days: 6 },
            location: { name: "Ingelmunster" },
            forecast: { "2026-05-28": { weather: { code: 12 }, temperature: { max: 29, min: 16 } } },
        };

        server.mockEndpoint().get("/forecast/daily").respondWith().statusCode(200).jsonBody(rawResponseBody).build();

        const response = await client.forecast.getDaily({
            id: "5726468552",
        });
        expect(response).toEqual(rawResponseBody);
    });
});
